// Simulate the redirect-based SSRF chain for the preview route
// get() uses fetch with redirect: follow, and isAllowed only checks a prefix.
// Confirm the metadata host is reachable via a redirect from trusted.example.test
// (trusted.example.test returns 302 -> http://169.254.169.254/...)
// We can also confirm open-redirect in continue.js:
const returnTo = "https://attacker.example.test/phish";
console.log("continue redirects to:", String(returnTo || "/"));
// No allowlist -> open redirect confirmed

// avatar: exactTrustedOrigin requires hostname images.example.test, port empty, https.
// With redirect:manual in fetch, no redirect follow. Check if userinfo trick can bypass:
const exactTrustedOrigin = (value) => {
  const parsed = new URL(value);
  return parsed.protocol === "https:" && parsed.hostname === "images.example.test" && parsed.port === "";
};
console.log("avatar https://images.example.test@169.254.169.254/ ->", exactTrustedOrigin("https://images.example.test@169.254.169.254/"));
console.log("  parsed host:", new URL("https://images.example.test@169.254.169.254/").hostname);
'"}

